CREATE SCHEMA shop;
CREATE TYPE shop.mood AS ENUM ('sad', 'ok', 'happy');
CREATE DOMAIN shop.price AS numeric(12, 2) DEFAULT 0 NOT NULL
  CHECK (VALUE >= 0) CONSTRAINT price_cap CHECK (VALUE < 1000000);
CREATE DOMAIN shop.code AS text COLLATE "C";
CREATE TYPE shop.money_pair AS (amount shop.price, label text COLLATE "C");
CREATE TYPE shop.span AS RANGE (subtype = timestamptz);
CREATE FUNCTION shop.add(a integer, b integer DEFAULT 1) RETURNS integer
  LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE AS 'SELECT a + b';
CREATE FUNCTION shop.labels(VARIADIC parts text[]) RETURNS SETOF text
  LANGUAGE sql STABLE AS 'SELECT unnest(parts)';
CREATE PROCEDURE shop.touch(INOUT counter integer)
  LANGUAGE plpgsql SECURITY DEFINER AS $$BEGIN counter := counter + 1; END$$;
CREATE TABLE shop.customers (
  id bigint GENERATED ALWAYS AS IDENTITY (START WITH 100 INCREMENT BY 5),
  email text COLLATE "C" NOT NULL,
  nick shop.code,
  mood shop.mood DEFAULT 'ok',
  balance shop.price,
  CONSTRAINT customers_pkey PRIMARY KEY (id),
  UNIQUE NULLS NOT DISTINCT (nick),
  CHECK (length(email) > 3),
  CHECK (email <> nick)
);
CREATE UNLOGGED TABLE shop.visits (
  id serial PRIMARY KEY,
  customer_id bigint NOT NULL,
  seen tstzrange NOT NULL,
  score integer DEFAULT shop.add(1, 2),
  CONSTRAINT visits_customer FOREIGN KEY (customer_id) REFERENCES shop.customers (id)
    ON DELETE CASCADE ON UPDATE RESTRICT DEFERRABLE INITIALLY DEFERRED,
  EXCLUDE USING gist (seen WITH &&)
);
CREATE TABLE shop.orders (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  customer_id bigint NOT NULL REFERENCES shop.customers (id) ON DELETE SET NULL (customer_id),
  total numeric(12, 2) NOT NULL CHECK (total >= 0),
  placed_at timestamptz NOT NULL DEFAULT now(),
  note varchar(200)
);
CREATE TABLE shop.tttttttttttttttttttttttttttttttttttttttttttttttttttttttttttt (
  cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc int UNIQUE CHECK (cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc > 0),
  x int, y int,
  CHECK (x < y), CHECK (x > 0), CHECK (x < 100),
  PRIMARY KEY (x)
);
CREATE INDEX ON shop.tttttttttttttttttttttttttttttttttttttttttttttttttttttttttttt (x, y);
CREATE INDEX ON shop.tttttttttttttttttttttttttttttttttttttttttttttttttttttttttttt (x, y);
CREATE INDEX orders_recent ON shop.orders (placed_at DESC NULLS LAST) INCLUDE (total) WHERE total > 0;
CREATE INDEX ON shop.orders (lower(note));
CREATE INDEX orders_note ON shop.orders USING hash (note);
CREATE VIEW shop.big_orders WITH (security_barrier = true) AS
  SELECT id, total FROM shop.orders WHERE total > 100;
CREATE VIEW shop.top_orders AS SELECT id FROM shop.big_orders WHERE total > 1000;
CREATE MATERIALIZED VIEW shop.totals AS
  SELECT customer_id, sum(total) AS amount FROM shop.orders GROUP BY customer_id;
CREATE UNIQUE INDEX totals_customer ON shop.totals (customer_id);
CREATE FUNCTION shop.audit() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RETURN NULL; END$$;
CREATE TRIGGER orders_audit AFTER INSERT OR UPDATE OF total OR DELETE ON shop.orders
  FOR EACH STATEMENT EXECUTE FUNCTION shop.audit();
CREATE TRIGGER orders_guard BEFORE UPDATE ON shop.orders
  FOR EACH ROW WHEN (OLD.total IS DISTINCT FROM NEW.total) EXECUTE FUNCTION shop.audit();
ALTER TABLE shop.orders ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_orders ON shop.orders AS RESTRICTIVE FOR SELECT TO ratel_reader
  USING (customer_id > 0);
CREATE POLICY insert_orders ON shop.orders FOR INSERT WITH CHECK (total < 1000000);
COMMENT ON SCHEMA shop IS 'Shop objects';
COMMENT ON VIEW shop.big_orders IS 'Orders over 100';
COMMENT ON FUNCTION shop.add(integer, integer) IS 'Adds';
COMMENT ON CONSTRAINT visits_customer ON shop.visits IS 'Visitor';
COMMENT ON TRIGGER orders_audit ON shop.orders IS 'Audit';
COMMENT ON POLICY own_orders ON shop.orders IS 'Own rows';
COMMENT ON INDEX shop.orders_recent IS 'Recent orders';
COMMENT ON SEQUENCE shop.visits_id_seq IS 'Visit ids';
GRANT USAGE ON SCHEMA shop TO ratel_reader;
GRANT SELECT, INSERT ON shop.orders TO ratel_reader WITH GRANT OPTION;
GRANT USAGE ON SEQUENCE shop.visits_id_seq TO ratel_reader;
GRANT EXECUTE ON FUNCTION shop.add(integer, integer) TO ratel_reader;
